// resizeExec applies terminal size changes to an exec session until resize is closed or ctx
// ends.
func (d *DockerRuntime) resizeExec(
	ctx context.Context,
	execID string,
	resize <-chan clablabruntime.TerminalSize,
) {
	for {
		select {
		case <-ctx.Done():
			return
		case size, ok := <-resize:
			if !ok || ctx.Err() != nil {
				return
			}
			err := d.Client.ContainerExecResize(ctx, execID, container.ResizeOptions{
				Height: uint(size.Height),
				Width:  uint(size.Width),
			})
			if err != nil {
				log.Debugf("failed to resize the terminal of exec %s: %v", execID, err)
			}
		}
	}
}

// InspectImage returns detailed information about a container image.
func (d *DockerRuntime) InspectImage(
	ctx context.Context,
	imageName string,
) (*clabruntime.ImageInspect, error) {
	imageData, _, err := d.Client.ImageInspectWithRaw(ctx, imageName)
	if err != nil {
		return nil, fmt.Errorf("failed to inspect image %s: %w", imageName, err)
	}

	// Convert Docker image inspect to our runtime ImageInspect
	labels := imageData.Config.Labels
	if labels == nil {
		labels = make(map[string]string)
	}

	// Extract GraphDriver data
	graphDriver := clabruntime.GraphDriver{
		Name: imageData.GraphDriver.Name,
		Data: clabruntime.GraphDriverData{},
	}

	// GraphDriver.Data is a map[string]string in Docker
	if upperDir, ok := imageData.GraphDriver.Data["UpperDir"]; ok {
		graphDriver.Data.UpperDir = upperDir
	}
	if workDir, ok := imageData.GraphDriver.Data["WorkDir"]; ok {
		graphDriver.Data.WorkDir = workDir
	}
	if mergedDir, ok := imageData.GraphDriver.Data["MergedDir"]; ok {
		graphDriver.Data.MergedDir = mergedDir
	}

	return &clabruntime.ImageInspect{
		ID: imageData.ID,
		Config: clabruntime.ImageConfig{
			Labels: labels,
		},
		RootFS: clabruntime.RootFS{
			Type:   imageData.RootFS.Type,
			Layers: imageData.RootFS.Layers,
		},
		GraphDriver: graphDriver,
	}, err
}

func (d *DockerRuntime) CopyToContainer(
	ctx context.Context,
	cID string,
	dstPath string,
	srcPath string,
) error {
	tarBuf, err := clabutils.FileToTarStream(dstPath, srcPath)
	if err != nil {
		return fmt.Errorf("error creating tar stream from source file %s: %w", srcPath, err)
	}

	opts := container.CopyToContainerOptions{
		AllowOverwriteDirWithFile: false,
	}

	log.Debugf("copying path %v -> %v to container %v", srcPath, dstPath, cID)
	err = d.Client.CopyToContainer(ctx, cID, filepath.Dir(dstPath), tarBuf, opts)
	if err != nil {
		return fmt.Errorf(
			"error copying path %v -> %v to container (%v): %w",
			srcPath,
			dstPath,
			cID,
			err,
		)
	}

	return nil
}

// convertVolumeMount takes a list of volumes in docker/clab format (src:dest:options)
// and converts them into Docker API mount.Mount structures.
func (d *DockerRuntime) convertVolumeMounts(mounts []string) ([]mount.Mount, error) {
	if len(mounts) == 0 {
		return nil, nil
	}

	docker_mounts := make([]mount.Mount, 0, len(mounts))

	for _, vol := range mounts {
		spec, err := clabtypes.NewVolumeFromString(vol)
		if err != nil {
			return nil, err
		}

		opts := clabtypes.ParseVolumeOptions(spec.Options())
		if len(opts.Unknown) > 0 {
			return nil, fmt.Errorf("unsupported volume option(s) %q in %q", opts.Unknown, vol)
		}

		m := mount.Mount{
			Type:     mount.TypeVolume,
			Target:   spec.Dst(),
			ReadOnly: opts.ReadOnly,
		}

		if opts.NoCopy {
			m.VolumeOptions = &mount.VolumeOptions{
				NoCopy: true,
			}
		}

		if spec.Src() != "" {
			m.Source = spec.Src()
		}

		log.Debugf("parsed volume %q into mount %+v", vol, m)
		docker_mounts = append(docker_mounts, m)
	}

	return docker_mounts, nil
}

