// LogNonRunningContainerOutput implements runtime.ContainerRuntime (no-op for Podman).
func (*PodmanRuntime) LogNonRunningContainerOutput(context.Context, string) {}

func (r *PodmanRuntime) Exec(
	ctx context.Context,
	cID string,
	execCmd *exec.ExecCmd,
) (*exec.ExecResult, error) {
	ctx, err := r.connect(ctx)
	if err != nil {
		return nil, err
	}
	execCreateConf := handlers.ExecCreateConfig{}
	execCreateConf.User = "root"
	execCreateConf.AttachStderr = true
	execCreateConf.AttachStdout = true
	execCreateConf.Cmd = execCmd.GetCmd()
	execID, err := containers.ExecCreate(ctx, cID, &execCreateConf)
	if err != nil {
		log.Errorf("failed to create exec in container %q: %v", cID, err)
		return nil, err
	}
	var sOut, sErr podmanWriterCloser
	execSAAOpts := new(
		containers.ExecStartAndAttachOptions,
	).WithOutputStream(&sOut).
		WithErrorStream(
			&sErr).
		WithAttachOutput(true).
		WithAttachError(true)

	err = containers.ExecStartAndAttach(ctx, execID, execSAAOpts)
	if err != nil {
		log.Errorf("failed to start/attach exec in container %q: %v", cID, err)
		return nil, err
	}
	// perform inspection to retrieve the exitcode
	inspectOut, err := containers.ExecInspect(ctx, execID, nil)
	if err != nil {
		return nil, err
	}
	log.Debugf(
		"Exec attached to the container %q and got stdout %q and stderr %q",
		cID,
		sOut.Bytes(),
		sErr.Bytes(),
	)

	// fill the execution result
	execResult := exec.NewExecResult(execCmd)
	execResult.SetStdErr(sErr.Bytes())
	execResult.SetStdOut(sOut.Bytes())
	execResult.SetReturnCode(inspectOut.ExitCode)

	return execResult, nil
}

